    39	use tree_sitter::Node;
    40	
    41	use crate::languages::get_node_text;
    42	
    43	/// Extract inheritance information from a Swift class declaration node.
    44	///
    45	/// Walks `inheritance_specifier` children of the class declaration. The first
    46	/// specifier is conventionally the superclass; subsequent specifiers are
    47	/// protocol conformances. Results use `extends`/`conforms` prefixes.
    48	#[must_use]
    49	pub fn extract_inheritance(node: &Node, source: &str) -> Vec<String> {
    50	    if node.kind() != "class_declaration" {
    51	        return Vec::new();
    52	    }
    53	
    54	    let mut inherits = Vec::new();
    55	    let mut seen_superclass = false;
    56	
    57	    for i in 0..node.child_count() {
    58	        if let Some(child) = node.child(i)
    59	            && child.kind() == "inheritance_specifier"
    60	            && let Some(type_node) = child.named_child(0)
    61	            && let Some(text) = get_node_text(&type_node, source)
    62	        {
    63	            // The superclass may carry generic arguments; keep the base name only.
    64	            let base = text.split('<').next().unwrap_or(&text).trim().to_string();
    65	            if seen_superclass {
    66	                inherits.push(format!("conforms {base}"));
    67	            } else {
    68	                inherits.push(format!("extends {base}"));
    69	                seen_superclass = true;
    70	            }
    71	        }
    72	    }
    73	
    74	    inherits
    75	}
